1	'use strict';
2	
3	// 按 duration_ns 计算基准统计量。
4	// 入参为已升序排序的整数数组（至少 1 个样本）。
5	// 浮点结果保留六位小数。
6	
7	function round6(value) {
8	  return Math.round(value * 1e6) / 1e6;
9	}
10	
11	function meanOf(values) {
12	  let sum = 0;
13	  for (const v of values) sum += v;
14	  return sum / values.length;
15	}
16	
17	function medianOfSorted(sorted) {
18	  const n = sorted.length;
19	  const mid = n >> 1;
20	  if (n % 2 === 1) return sorted[mid];
21	  // 偶数样本取中间两值平均（可能为 x.5，无需 round6 也会被统一处理）
22	  return (sorted[mid - 1] + sorted[mid]) / 2;
23	}
24	
25	function p95OfSorted(sorted) {
26	  const n = sorted.length;
27	  // 排序后第 ceil(0.95 * count) 项（1-based -> 转 0-based）
28	  const rank = Math.ceil(0.95 * n);
29	  return sorted[rank - 1];
30	}
31	
32	function stddevPopulation(values, avg) {
33	  let acc = 0;
34	  for (const v of values) {
35	    const d = v - avg;
36	    acc += d * d;
37	  }
38	  return Math.sqrt(acc / values.length);
39	}
40	
41	function computeSummary(durations) {
42	  const sorted = durations.slice().sort((a, b) => a - b);
43	  const count = sorted.length;
44	  const min = sorted[0];
45	  const max = sorted[count - 1];
46	  const mean = meanOf(sorted);
47	  const median = medianOfSorted(sorted);
48	  const p95 = p95OfSorted(sorted);
49	  const stddev = stddevPopulation(sorted, mean);
50	  return {
51	    count,
52	    min,
53	    max,
54	    mean: round6(mean),
55	    median: round6(median),
56	    p95,
57	    stddev: round6(stddev),
58	  };
59	}
60	
61	// ---- Welch 双侧 t 检验 ----
62	// 无第三方依赖，t 分布 CDF 经正则化不完全 beta 函数求得：
63	// 双侧 p = I_{df/(df+t^2)}(df/2, 1/2)。
64	
65	// Lanczos 近似系数（g = 7, n = 9）
66	const LANCZOS = [
67	  0.99999999999980993,
68	  676.5203681218851,
69	  -1259.1392167224028,
70	  771.32342877765313,
71	  -176.61502916214059,
72	  12.507343278686905,
73	  -0.13857109526572012,
74	  9.9843695780195716e-6,
75	  1.5056327351493116e-7,
76	];
77	
78	function logGamma(z) {
79	  if (z < 0.5) {
80	    // 反射公式
81	    return Math.log(Math.PI / Math.sin(Math.PI * z)) - logGamma(1 - z);
82	  }
83	  const w = z - 1;
84	  let x = LANCZOS[0];
85	  for (let i = 1; i < LANCZOS.length; i++) {
86	    x += LANCZOS[i] / (w + i);
87	  }
88	  const t = w + 7.5;
89	  return 0.5 * Math.log(2 * Math.PI) + (w + 0.5) * Math.log(t) - t + Math.log(x);
90	}
91	
92	// Lentz 连分式求值（Numerical Recipes betacf）
93	function betaContinuedFraction(a, b, x) {
94	  const MAX_ITER = 200;
95	  const EPS = 3e-14;
96	  const FPMIN = 1e-300;
97	  const qab = a + b;
98	  const qap = a + 1;
99	  const qam = a - 1;
100	  let c = 1;
101	  let d = 1 - (qab * x) / qap;
102	  if (Math.abs(d) < FPMIN) d = FPMIN;
103	  d = 1 / d;
104	  let h = d;
105	  for (let m = 1; m <= MAX_ITER; m++) {
106	    const m2 = 2 * m;
107	    let aa = (m * (b - m) * x) / ((qam + m2) * (a + m2));
108	    d = 1 + aa * d;
109	    if (Math.abs(d) < FPMIN) d = FPMIN;
110	    c = 1 + aa / c;
111	    if (Math.abs(c) < FPMIN) c = FPMIN;
112	    d = 1 / d;
113	    h *= d * c;
114	    aa = (-(a + m) * (qab + m) * x) / ((a + m2) * (qap + m2));
115	    d = 1 + aa * d;
116	    if (Math.abs(d) < FPMIN) d = FPMIN;
117	    c = 1 + aa / c;
118	    if (Math.abs(c) < FPMIN) c = FPMIN;
119	    d = 1 / d;
120	    const del = d * c;
121	    h *= del;
122	    if (Math.abs(del - 1) < EPS) break;
123	  }
124	  return h;
125	}
126	
127	// 正则化不完全 beta 函数 I_x(a, b)
128	function regularizedIncompleteBeta(x, a, b) {
129	  if (x <= 0) return 0;
130	  if (x >= 1) return 1;
131	  const lnFront =
132	    a * Math.log(x) + b * Math.log(1 - x) +
133	    logGamma(a + b) - logGamma(a) - logGamma(b);
134	  const front = Math.exp(lnFront);
135	  if (x < (a + 1) / (a + b + 2)) {
136	    return (front * betaContinuedFraction(a, b, x)) / a;
137	  }
138	  return 1 - (front * betaContinuedFraction(b, a, 1 - x)) / b;
139	}
140	
141	// 样本方差（无偏，除以 n-1）；调用方保证 values.length >= 2
142	function sampleVariance(values, avg) {
143	  let acc = 0;
144	  for (const v of values) {
145	    const d = v - avg;
146	    acc += d * d;
147	  }
148	  return acc / (values.length - 1);
149	}
150	
151	// 双侧 Welch t 检验：baseline 与 candidate 均为至少 2 个样本的数组。
152	// t 取候选减基线方向。返回保留六位小数的
153	// { t_statistic, degrees_of_freedom, p_value }。
154	// 两边方差均为 0 的退化情形：均值相同 -> {0, null, 1}；均值不同 -> {null, null, 0}。
155	function welchTest(baseline, candidate) {
156	  const n1 = baseline.length;
157	  const n2 = candidate.length;
158	  const m1 = meanOf(baseline);
159	  const m2 = meanOf(candidate);
160	  const v1 = sampleVariance(baseline, m1);
161	  const v2 = sampleVariance(candidate, m2);
162	
163	  if (v1 === 0 && v2 === 0) {
164	    if (m1 === m2) {
165	      return { t_statistic: 0, degrees_of_freedom: null, p_value: 1 };
166	    }
167	    return { t_statistic: null, degrees_of_freedom: null, p_value: 0 };
168	  }
169	
170	  const s1 = v1 / n1;
171	  const s2 = v2 / n2;
172	  const t = (m2 - m1) / Math.sqrt(s1 + s2);
173	  const df = (s1 + s2) ** 2 / (s1 ** 2 / (n1 - 1) + s2 ** 2 / (n2 - 1));
174	  const p = regularizedIncompleteBeta(df / (df + t * t), df / 2, 0.5);
175	  return {
176	    t_statistic: round6(t),
177	    degrees_of_freedom: round6(df),
178	    p_value: round6(p),
179	  };
180	}
181	
182	// 双侧配对 t 检验：deltas 为逐对候选减基线差值（至少 2 个）。
183	// t = mean / (sample_stddev / sqrt(count))，degrees_of_freedom = count - 1，
184	// p 与 welchTest 同一口径：I_{df/(df+t^2)}(df/2, 1/2)。
185	// 差值零方差的退化情形与 welchTest 一致：均值为 0 -> {0, null, 1}；
186	// 均值非 0 -> {null, null, 0}。
187	function pairedTTest(deltas) {
188	  const n = deltas.length;
189	  const m = meanOf(deltas);
190	  const v = sampleVariance(deltas, m);
191	
192	  if (v === 0) {
193	    if (m === 0) {
194	      return { t_statistic: 0, degrees_of_freedom: null, p_value: 1 };
195	    }
196	    return { t_statistic: null, degrees_of_freedom: null, p_value: 0 };
197	  }
198	
199	  const t = m / Math.sqrt(v / n);
200	  const df = n - 1;
201	  const p = regularizedIncompleteBeta(df / (df + t * t), df / 2, 0.5);
202	  return {
203	    t_statistic: round6(t),
204	    degrees_of_freedom: df,
205	    p_value: round6(p),
206	  };
207	}
208	
209	// 配对均值差（候选减基线）的双侧（1 - alpha）区间，内部原始（未取整）值。
210	// deltas 为至少 2 个逐对差值，0 < alpha < 1；baselineMean 为成对基线样本均值，
211	// 为 0 时两个百分比端点为 null。差值零方差时区间退化为单点（两端均为差值均值），
212	// 不反解临界值；与 welchMeanInterval 的退化口径一致。
213	function pairedMeanInterval(deltas, baselineMean, alpha) {
214	  const n = deltas.length;
215	  const m = meanOf(deltas);
216	  const v = sampleVariance(deltas, m);
217	
218	  let lower;
219	  let upper;
220	  if (v === 0) {
221	    lower = m;
222	    upper = m;
223	  } else {
224	    const margin = tCriticalValue(n - 1, alpha) * Math.sqrt(v / n);
225	    lower = m - margin;
226	    upper = m + margin;
227	  }
228	
229	  return {
230	    level: 1 - alpha,
231	    lower_ns: lower,
232	    upper_ns: upper,
233	    lower_percent: baselineMean === 0 ? null : (lower / baselineMean) * 100,
234	    upper_percent: baselineMean === 0 ? null : (upper / baselineMean) * 100,
235	  };
236	}
237	
238	// t 分布双侧尾概率：给定自由度 df 与 t >= 0，返回 P(|T| >= t)。
239	// 与 welchTest 的 p 值同一口径：I_{df/(df+t^2)}(df/2, 1/2)。
240	function tTwoTailedP(df, t) {
241	  return regularizedIncompleteBeta(df / (df + t * t), df / 2, 0.5);
242	}
243	
244	// 反解双侧临界值 t*（t* >= 0），使 tTwoTailedP(df, t*) = twoTailedP。
245	// t>=0 上双侧尾概率随 t 严格单调递减：先倍增找上界，再二分收敛。
246	// 调用方保证 df > 0、0 < twoTailedP < 1。
247	function tCriticalValue(df, twoTailedP) {
248	  let hi = 1;
249	  while (tTwoTailedP(df, hi) > twoTailedP) {
250	    hi *= 2;
251	  }
252	  let lo = 0;
253	  for (let i = 0; i < 200; i++) {
254	    const mid = (lo + hi) / 2;
255	    if (tTwoTailedP(df, mid) > twoTailedP) {
256	      lo = mid;
257	    } else {
258	      hi = mid;
259	    }
260	  }
261	  return (lo + hi) / 2;
262	}
263	
264	// 候选均值减基线均值差的双侧 Welch（1 - alpha）区间，内部原始（未取整）值。
265	// baseline 与 candidate 均为至少 2 个样本的数组，0 < alpha < 1。
266	// 返回 { level, lower_ns, upper_ns, lower_percent, upper_percent }；
267	// 基线均值为 0 时两个百分比端点为 null。
268	// 两边方差均为 0 的退化情形：区间退化为单点，两端均为候选减基线均值
269	// （均值相同即两端为 0），不反解临界值；welch 与 decision 仍走 welchTest 口径。
270	function welchMeanInterval(baseline, candidate, alpha) {
271	  const n1 = baseline.length;
272	  const n2 = candidate.length;
273	  const m1 = meanOf(baseline);
274	  const m2 = meanOf(candidate);
275	  const v1 = sampleVariance(baseline, m1);
276	  const v2 = sampleVariance(candidate, m2);
277	  const diff = m2 - m1;
278	
279	  let lower;
280	  let upper;
281	  if (v1 === 0 && v2 === 0) {
282	    lower = diff;
283	    upper = diff;
284	  } else {
285	    const s1 = v1 / n1;
286	    const s2 = v2 / n2;
287	    const standardError = Math.sqrt(s1 + s2);
288	    const df = (s1 + s2) ** 2 / (s1 ** 2 / (n1 - 1) + s2 ** 2 / (n2 - 1));
289	    const margin = tCriticalValue(df, alpha) * standardError;
290	    lower = diff - margin;
291	    upper = diff + margin;
292	  }
293	
294	  return {
295	    level: 1 - alpha,
296	    lower_ns: lower,
297	    upper_ns: upper,
298	    lower_percent: m1 === 0 ? null : (lower / m1) * 100,
299	    upper_percent: m1 === 0 ? null : (upper / m1) * 100,
300	  };
301	}
302	
303	// ---- Mann-Whitney U 双侧检验 ----
304	// 无第三方依赖。优先按秩和分布精确计算：合并排序后按相等值分 tie 组取平均秩，
305	// 以动态规划枚举 A 侧（baseline）从各 tie 组中选取 k 个的组合数，得到 A 侧
306	// 秩和 R（等价于 U = R - n1(n1+1)/2）的分布，双侧 p 取
307	// min(1, 2·min(P(U <= U_obs), P(U >= U_obs)))：两倍较小尾概率（精确置换分布
308	// 下 Mann-Whitney 双侧检验的通用约定）。
309	//
310	// DP 状态数随样本量三次方增长，因此按工作量自适应：转换数在预算内（小样本，
311	// 或大样本但并列很多导致秩空间被压缩）时给精确值；超出预算或计数溢出时回退到
312	// tie 校正正态近似（含连续性校正）：
313	//   z = (|U - n1*n2/2| - 0.5) / sigma，sigma^2 含 Σ(t^3-t) tie 修正，
314	//   双侧 p = erfc(z / sqrt(2))。
315	//
316	// 精确计数用 Number：恒为非负计数的线性累加（无抵消），比值相对误差约
317	// O(n·eps)；仅当计数超过安全范围（MW_EXACT_COUNT_MAX）时才回退，避免大组合数
318	// 下整数舍入放大。
319	
320	const MW_EXACT_TRANSITION_BUDGET = 100_000;
321	const MW_EXACT_COUNT_MAX = 1e15;
322	
323	// 互补误差函数 erfc(x)，Abramowitz-Stegun 7.1.26（相对误差 < 1.5e-7）。
324	// 仅用于大样本正态近似尾概率。
325	function erfc(x) {
326	  const z = Math.abs(x);
327	  const t = 1 / (1 + 0.5 * z);
328	  const tau = t * Math.exp(
329	    -z * z - 1.26551223
330	      + t * (1.00002368
331	        + t * (0.37409196
332	          + t * (0.09678418
333	            + t * (-0.18628806
334	              + t * (0.27886807
335	                + t * (-1.13520398
336	                  + t * (1.48851587
337	                    + t * (-0.82215223
338	                      + t * 0.17087277)))))))),
339	  );
340	  return x >= 0 ? tau : 2 - tau;
341	}
342	
343	// 组合数 C(n, k)（Number）。仅在小 n 上调用，调用方另做溢出检查。
344	function binomialCount(n, k) {
345	  if (k < 0 || k > n) return 0;
346	  const kk = Math.min(k, n - k);
347	  let num = 1;
348	  let den = 1;
349	  for (let i = 0; i < kk; i++) {
350	    num *= n - i;
351	    den *= i + 1;
352	  }
353	  return num / den;
354	}
355	
356	// 返回双侧 p 值（内部原始值，未取整）。baseline/candidate 均为数值数组，
357	// 可含并列；调用方保证两侧均至少 1 个观测。
358	function mannWhitneyTwoSided(baseline, candidate) {
359	  const n1 = baseline.length;
360	  const n2 = candidate.length;
361	  const n = n1 + n2;
362	
363	  // 合并排序并按相等值分 tie 组：{ size, avgRank, aObserved }。
364	  const merged = [];
365	  for (const v of baseline) merged.push({ v, side: 1 });
366	  for (const v of candidate) merged.push({ v, side: 2 });
367	  merged.sort((a, b) => a.v - b.v);
368	  const tieGroups = [];
369	  for (let i = 0; i < merged.length;) {
370	    let j = i;
371	    while (j < merged.length && merged[j].v === merged[i].v) j++;
372	    const size = j - i;
373	    // 该 tie 组占据秩 i+1 .. j（1-based）
374	    const avgRank = ((i + 1) + j) / 2;
375	    let a = 0;
376	    for (let k = i; k < j; k++) {
377	      if (merged[k].side === 1) a++;
378	    }
379	    tieGroups.push({ size, avgRank, aObserved: a });
380	    i = j;
381	  }
382	
383	  // 观测到的 A 侧秩和与 U
384	  let rObserved = 0;
385	  for (const g of tieGroups) rObserved += g.aObserved * g.avgRank;
386	  const uObserved = rObserved - (n1 * (n1 + 1)) / 2;
387	
388	  // 自适应精确 DP：layers 按已选 A 侧个数分层 Map(chosen -> Map(秩和 -> 计数))，
389	  // 最终只统计 chosen === n1 的配置。转换数超预算或计数超安全范围则放弃精确解。
390	  let layers = new Map([[0, new Map([[0, 1]])]]);
391	  let transitions = 0;
392	  let exactUsable = true;
393	  let aborted = false;
394	
395	  outer:
396	  for (const g of tieGroups) {
397	    const next = new Map();
398	    for (const [chosen, sums] of layers) {
399	      for (const [sum, cnt] of sums) {
400	        for (let k = 0; k <= g.size; k++) {
401	          const newChosen = chosen + k;
402	          if (newChosen > n1) break;
403	          let layer = next.get(newChosen);
404	          if (!layer) {
405	            layer = new Map();
406	            next.set(newChosen, layer);
407	          }
408	          const ways = cnt * binomialCount(g.size, k);
409	          if (!Number.isFinite(ways) || ways > MW_EXACT_COUNT_MAX) {
410	            exactUsable = false;
411	            break outer;
412	          }
413	          const key = sum + k * g.avgRank;
414	          const mergedCount = (layer.get(key) || 0) + ways;
415	          if (mergedCount > MW_EXACT_COUNT_MAX) {
416	            exactUsable = false;
417	            break outer;
418	          }
419	          layer.set(key, mergedCount);
420	          transitions++;
421	          if (transitions > MW_EXACT_TRANSITION_BUDGET) {
422	            aborted = true;
423	            break outer;
424	          }
425	        }
426	      }
427	    }
428	    layers = next;
429	  }
430	
431	  if (exactUsable && !aborted) {
432	    const valid = layers.get(n1);
433	    if (valid) {
434	      let total = 0;
435	      let lowerOrEqual = 0;
436	      let greaterOrEqual = 0;
437	      for (const [sum, cnt] of valid) {
438	        total += cnt;
439	        if (sum <= rObserved) lowerOrEqual += cnt;
440	        if (sum >= rObserved) greaterOrEqual += cnt;
441	      }
442	      if (total > 0) {
443	        const p = 2 * Math.min(lowerOrEqual / total, greaterOrEqual / total);
444	        return p > 1 ? 1 : p;
445	      }
446	    }
447	    return 1;
448	  }
449	
450	  // tie 校正正态近似。
451	  const meanU = (n1 * n2) / 2;
452	  let tieTerm = 0;
453	  for (const g of tieGroups) {
454	    tieTerm += g.size ** 3 - g.size;
455	  }
456	  const variance = (n1 * n2 / 12) * ((n + 1) - tieTerm / (n * (n - 1)));
457	  if (variance <= 0) {
458	    return uObserved === meanU ? 1 : 0;
459	  }
460	  let z = (Math.abs(uObserved - meanU) - 0.5) / Math.sqrt(variance);
461	  if (z < 0) z = 0;
462	  const p = erfc(z / Math.SQRT2);
463	  return p > 1 ? 1 : p;
464	}
465	
466	module.exports = {
467	  computeSummary,
468	  round6,
469	  welchTest,
470	  pairedTTest,
471	  pairedMeanInterval,
472	  tCriticalValue,
473	  welchMeanInterval,
474	  mannWhitneyTwoSided,
475	};
