21	function writeCollect(dir, name, durations, { command = 'true', unit = 'ns' } = {}) {
22	  const samples = durations.map((d, i) => ({
23	    index: i,
24	    started_at: '2026-01-01T00:00:00.000Z',
25	    duration_ns: d,
26	    exit_code: 0,
27	  }));
28	  const report = { command, runs: durations.length, warmup: 0, timeout_ms: 1000,
29	    unit, samples, summary: {}, errors: [] };
30	  const p = path.join(dir, name);
31	  fs.writeFileSync(p, JSON.stringify(report));
32	  return p;
33	}
