230	test('confidence_interval：alpha 只改变 level 与区间宽度，p 值/decision/字段不受影响', () => {
231	  const dir = tempDir();
232	  const baseline = writeCollect(dir, 'base.json', [1, 2, 3]);
233	  const candidate = writeCollect(dir, 'cand.json', [4, 5, 6]);
234	  const run = (alpha) => {
235	    const out = path.join(dir, `a-${alpha}.json`);
236	    const rr = runCli(['--baseline', baseline, '--candidate', candidate,
237	      '--output', out, '--alpha', String(alpha)]);
238	    assert.equal(rr.status, 0, rr.stderr);
239	    return readJson(out);
240	  };
241	  const r95 = run(0.05);
242	  const r90 = run(0.1);
243	  assert.equal(r95.delta.mean.confidence_interval.level, 0.95);
244	  assert.equal(r90.delta.mean.confidence_interval.level, 0.9);
245	  // 同一输入下 Welch 完全一致
246	  assert.deepEqual(r95.welch, r90.welch);
247	  assert.deepEqual(r95.decision, r90.decision);
248	  assert.deepEqual(r95.attribution, r90.attribution);
249	  // 点估计不变，仅区间随置信度变窄
250	  assert.equal(r95.delta.mean.ns, r90.delta.mean.ns);
251	  const w95 = r95.delta.mean.confidence_interval.upper_ns
252	    - r95.delta.mean.confidence_interval.lower_ns;
253	  const w90 = r90.delta.mean.confidence_interval.upper_ns
254	    - r90.delta.mean.confidence_interval.lower_ns;
255	  assert.ok(w90 < w95);
256	  // 区间关于点估计对称（Welch 区间）
257	  const mid = (ci) => (ci.lower_ns + ci.upper_ns) / 2;
258	  assert.equal(Math.round(mid(r95.delta.mean.confidence_interval) * 1e6) / 1e6,
259	    r95.delta.mean.ns);
260	});
