// t 分布 CDF：P(T <= t)，df > 0。与 welchTest 的 p 值同一口径。
function tCdf(df, t) {
  if (t === 0) return 0.5;
  const twoTailed = tTwoTailedP(df, Math.abs(t));
  return t > 0 ? 1 - twoTailed / 2 : twoTailed / 2;
}

// Welch 两样本的均值、均值差（候选减基线）、标准误与自由度，
// 内部原始（未取整）值，供 equivalence 的 TOST 单侧检验使用。
// 两侧方差均为 0 时 standardError 为 0、degrees_of_freedom 为 null。
function welchStandardError(baseline, candidate) {
  const n1 = baseline.length;
  const n2 = candidate.length;
  const m1 = meanOf(baseline);
  const m2 = meanOf(candidate);
  const v1 = sampleVariance(baseline, m1);
  const v2 = sampleVariance(candidate, m2);
  const diff = m2 - m1;

  if (v1 === 0 && v2 === 0) {
    return {
      baselineMean: m1,
      candidateMean: m2,
      diff,
      standardError: 0,
      degreesOfFreedom: null,
    };
  }

  const s1 = v1 / n1;
  const s2 = v2 / n2;
  const standardError = Math.sqrt(s1 + s2);
  const df = (s1 + s2) ** 2 / (s1 ** 2 / (n1 - 1) + s2 ** 2 / (n2 - 1));
  return {
    baselineMean: m1,
    candidateMean: m2,
    diff,
    standardError,
    degreesOfFreedom: df,
  };
}

