    { t_statistic: 0, degrees_of_freedom: null, p_value: 1 });
  assert.equal(result.equivalence_test.lower.p_value, 0);
  assert.equal(result.decision, 'above_margin');

  // 差值恰为 -margin：lower 的 p 为 1 -> below_margin
